import numpy as np, ot

def emd_perm(n):
    a=ot.utils.unif(n)
    M=np.zeros((n,n))
    G=ot.lp.emd(a,a,M,check_marginals=False)
    # extract permutation indices: for each row, find col where G>0.
    return np.argmax(G, axis=1)
for n in range(2,11):
    p=emd_perm(n)
    print(n,p)
